-- v0.237 (dados) — Diagnóstico Mathisa (pré-diagnóstico): devolve ao cliente o botão de anexar os arquivos.
-- O que aconteceu: a pergunta 17 ("Precisamos dos arquivos…") foi salva pelo editor de perguntas, que apagava a configuração que ele não mostra:
-- anexar no formulário (upload), sem "Mando depois", a ligação com "Onde vende?" (grupos por plataforma), o período e as planilhas-modelo.
-- Sem "upload", o formulário só perguntava "Tenho / Não tenho", sem lugar para anexar. O editor foi corrigido na v0.237.
-- Este script põe de volta a configuração do modelo, ligada à pergunta "Onde vende?" deste formulário.
-- Só mexe nesta pergunta. Pode rodar de novo sem problema. Rode em qualquer ordem depois do RODAR_v0.228.
do $f$
declare v_q uuid := '0a039a99-7aa6-496c-b27d-28579c4df500'; v_onde uuid := '3c12abe3-0778-44d2-b318-32de281ec670';
begin
  if not exists (select 1 from pesquisa_perguntas where id = v_q and tipo = 'documentos' and pesquisa_id = '951543b9-18d5-4920-af17-bf8a44c04d62') then
    raise exception 'Pergunta de arquivos do "Diagnóstico Mathisa (pré-diagnóstico)" não encontrada.'; end if;
  if not exists (select 1 from pesquisa_perguntas where id = v_onde and pesquisa_id = '951543b9-18d5-4920-af17-bf8a44c04d62') then
    raise exception 'Pergunta "Onde vende?" não encontrada neste formulário.'; end if;
  update pesquisa_perguntas set config = '{"categorias": [{"k": "vendas_hotmart", "l": "Vendas da Hotmart", "se": ["Hotmart"], "d": "No painel da Hotmart, exporte o relatório de vendas do período (CSV ou Excel), do jeito que sai, com todas as vendas, inclusive reembolsos e cancelamentos. Não precisa arrumar nada: nós fazemos o de-para das colunas."}, {"k": "vendas_kiwify", "l": "Vendas da Kiwify", "se": ["Kiwify"], "d": "No painel da Kiwify, exporte o relatório de vendas do período (CSV ou Excel), do jeito que sai, com todas as vendas, inclusive reembolsos e cancelamentos. Não precisa arrumar nada: nós fazemos o de-para das colunas."}, {"k": "vendas_eduzz", "l": "Vendas da Eduzz", "se": ["Eduzz"], "d": "No painel da Eduzz, exporte o relatório de vendas do período (CSV ou Excel), do jeito que sai, com todas as vendas, inclusive reembolsos e cancelamentos. Não precisa arrumar nada: nós fazemos o de-para das colunas."}, {"k": "vendas_hubla", "l": "Vendas da Hubla", "se": ["Hubla"], "d": "No painel da Hubla, exporte o relatório de vendas do período (CSV ou Excel), do jeito que sai, com todas as vendas, inclusive reembolsos e cancelamentos. Não precisa arrumar nada: nós fazemos o de-para das colunas."}, {"k": "vendas", "l": "Vendas fora das plataformas", "se": ["Contrato direto", "Loja própria", "Outro", "_nenhuma"], "d": "As vendas que não passam pelas plataformas (contrato direto, loja própria, outra), uma por linha: data, produto, valor, status (aprovada, reembolsada, cancelada) e o e-mail do cliente. Use a planilha-modelo.", "cols": ["data_venda", "produto", "valor", "status", "plataforma", "email_cliente", "nome_cliente", "telefone", "forma_pagamento", "parcelas", "utm_source", "utm_campaign"], "ex": ["15/03/2026", "Curso Exemplo", "997,00", "aprovada", "Hotmart", "maria@email.com", "Maria Silva", "(11) 98888-7777", "cartão", "12", "instagram", "lancamento-marco"]}, {"k": "alunos", "l": "Clientes", "d": "Quem já comprou: nome, e-mail, telefone, produto, quando entrou e a situação hoje (ativo, inativo, cancelado). A lista de alunos da área de membros também serve.", "cols": ["nome", "email", "telefone", "produto", "data_entrada", "situacao", "data_cancelamento"], "ex": ["Maria Silva", "maria@email.com", "(11) 98888-7777", "Curso Exemplo", "15/03/2026", "ativo", ""]}, {"k": "crm", "l": "Leads", "d": "Os leads do período: nome, e-mail, telefone, data de entrada e de onde vieram (origem ou UTM). Pode ser a exportação da ferramenta de e-mail, do CRM ou a planilha do lançamento.", "cols": ["nome", "email", "telefone", "data_entrada", "origem", "utm_source", "utm_campaign", "etapa", "resultado"], "ex": ["João Souza", "joao@email.com", "(21) 97777-6666", "02/03/2026", "anúncio", "facebook", "lancamento-marco", "qualificado", "ganho"]}, {"k": "marketing", "l": "Investimento em anúncios", "d": "Quanto investiu por mês em cada canal (Meta Ads, Google Ads…). O relatório do gerenciador de anúncios por mês também serve.", "cols": ["mes", "canal", "investimento", "impressoes", "cliques", "leads", "vendas"], "ex": ["03/2026", "Meta Ads", "5000,00", "250000", "4200", "610", "23"]}, {"k": "financeiro", "l": "Custos da operação (opcional)", "d": "Se quiser ver o lucro no planejamento: os custos por mês (equipe, ferramentas, pró-labore). Se não quiser, marque \"Não tenho\".", "cols": ["mes", "descricao", "valor", "tipo"], "ex": ["03/2026", "Equipe", "8000,00", "fixo"]}], "upload": true, "sem_depois": true, "onde": "3c12abe3-0778-44d2-b318-32de281ec670", "aviso": "Não envie senhas nem acessos em planilhas ou documentos. Os arquivos ficam num local privado e só a equipe que atende você vê. Os dados pessoais são tratados conforme a LGPD.", "periodo": {"de": "nov/2025", "ate": "out/2026", "txt": "dos últimos 12 meses completos (de nov/2025 a out/2026)"}}'::jsonb where id = v_q;
  raise notice 'Pergunta de arquivos restaurada: o cliente volta a anexar os arquivos no formulário.';
end $f$;
